//! The saved state: the reverb type and preset, the active type's parameter
//! slots (generated by `model/rustgen.py`, included from `ui.rs`), each
//! slot's depth for the two control voltages, and the settings. The opts
//! crate stores them in flash; the screen and its navigation are `ui.rs` and
//! `screen.rs`, not the opts menu.
//!
//! A parameter page is a row of slots. Each slot holds the parameter the
//! running program puts there (`ParamDecl::page` and `slot`), so one set of
//! slots serves every type; `set_active` changes which program that is.

use core::fmt::Write;
use core::sync::atomic::{AtomicUsize, Ordering};

use bfr_cpu::cv;
use bfr_cpu::program::{N_PROGRAMS, PROGRAMS};
use bfr_cpu::types::{ParamDecl, Program};
use opts::*;
use serde_derive::{Deserialize, Serialize};
use strum_macros::{EnumIter, IntoStaticStr};

static ACTIVE: AtomicUsize = AtomicUsize::new(0);

/// Index in `PROGRAMS` of the program the menu shows.
pub fn active() -> usize {
    ACTIVE.load(Ordering::Relaxed)
}

pub fn set_active(k: usize) {
    ACTIVE.store(k.min(N_PROGRAMS - 1), Ordering::Relaxed);
}

/// The program the menu shows.
pub fn program() -> &'static Program {
    PROGRAMS[active()]
}

/// A slot's grid index before anything set it (a fresh menu, or a slot the
/// saved options didn't have).
pub const UNSET: u16 = u16::MAX;

/// A parameter value in its own units, short enough for a dial (e.g.
/// "8.00kHz", "250ms", "0.35").
/// `{}`s `.0` with `.1` digits after the point (and `+` before a positive
/// value with `.2`), in integer arithmetic: core's float formatting is about
/// 16 KB of firmware.
pub struct Fixed(pub f64, pub usize, pub bool);

impl core::fmt::Display for Fixed {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let Fixed(v, decimals, plus) = *self;
        let scale = 10u64.pow(decimals as u32);
        let neg = v < 0.0;
        let m = ((if neg { -v } else { v }) * scale as f64 + 0.5) as u64;
        let sign = if neg && m != 0 { "-" } else if plus { "+" } else { "" };
        if decimals == 0 {
            write!(f, "{}{}", sign, m)
        } else {
            write!(f, "{}{}.{:0w$}", sign, m / scale, m % scale, w = decimals)
        }
    }
}

pub fn format_value(d: &ParamDecl, v: f64) -> OptionString {
    let mut s = OptionString::new();
    // a MIDI note number, by name ("note": A2); a choice ("|a|b|c": by index)
    if d.unit == "note" {
        const NAMES: [&str; 12] = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
        let n = (v + 0.5) as i32;
        write!(&mut s, "{}{}", NAMES[n.rem_euclid(12) as usize], n.div_euclid(12) - 1).ok();
        return s;
    }
    if let Some(choices) = d.unit.strip_prefix('|') {
        let i = (v.max(0.0) + 0.5) as usize;
        s.push_str(choices.split('|').nth(i).unwrap_or("?")).ok();
        return s;
    }
    let mut v = v as f32;
    let mut unit = d.unit;
    if unit == "Hz" && v >= 1000.0 {
        v /= 1000.0;
        unit = "kHz";
    }
    let a = if v < 0.0 { -v } else { v };
    let decimals = if d.decimals >= 0 {
        d.decimals as usize
    } else if a >= 100.0 {
        0
    } else if a >= 10.0 {
        1
    } else {
        2
    };
    write!(&mut s, "{}{}", Fixed(v as f64, decimals, false), unit).ok();
    s
}

/// One parameter slot of a page, shown in the parameter's own units.
#[derive(Clone)]
pub struct ParamOption {
    page: u8,
    slot: u8,
    /// Position on the parameter's grid (`ParamDecl::at`).
    pub index: u16,
    key: OptionKey,
}

impl ParamOption {
    pub fn new(page: u8, slot: u8, key: u32) -> Self {
        Self { page, slot, index: UNSET, key: OptionKey::new(key) }
    }

    /// Index in the active program's `params` of the parameter in this slot.
    pub fn param(&self) -> Option<usize> {
        program().params.iter().position(|d| d.page == self.page && d.slot == self.slot)
    }

    pub fn decl(&self) -> Option<&'static ParamDecl> {
        self.param().map(|i| &program().params[i])
    }

    /// The active program has a parameter in this slot.
    pub fn in_use(&self) -> bool {
        self.param().is_some()
    }

    pub fn is(&self, d: &ParamDecl) -> bool {
        d.page == self.page && d.slot == self.slot
    }

    /// The parameter value the menu shows.
    pub fn param_value(&self) -> f64 {
        self.decl().map(|d| d.at(self.index.min(d.steps))).unwrap_or(0.0)
    }
}

impl OptionTrait for ParamOption {
    fn name(&self) -> &'static str {
        self.decl().map(|d| d.label).unwrap_or("-")
    }

    fn value(&self) -> OptionString {
        match self.decl() {
            Some(d) => format_value(d, self.param_value()),
            None => {
                let mut s = OptionString::new();
                s.push('-').ok();
                s
            }
        }
    }

    fn tick_up(&mut self) {
        if let Some(d) = self.decl() {
            if self.index < d.steps {
                self.index += 1;
            }
        }
    }

    fn tick_down(&mut self) {
        if self.decl().is_some() && self.index > 0 {
            self.index -= 1;
        }
    }

    fn percent(&self) -> f32 {
        self.decl().map(|d| self.index.min(d.steps) as f32 / d.steps as f32).unwrap_or(0.0)
    }

    fn n_unique_values(&self) -> usize {
        self.decl().map(|d| d.steps as usize + 1).unwrap_or(1)
    }

    fn key(&self) -> &OptionKey {
        &self.key
    }

    fn key_mut(&mut self) -> &mut OptionKey {
        &mut self.key
    }

    // The value is saved whatever the type; it is clamped to the type's grid
    // when the type loads (`App::load_type`).
    fn encode(&self, buf: &mut [u8]) -> Option<usize> {
        if self.index != UNSET && buf.len() >= 2 {
            buf[..2].copy_from_slice(&self.index.to_le_bytes());
            Some(2)
        } else {
            None
        }
    }

    fn decode(&mut self, buf: &[u8]) -> bool {
        if buf.len() < 2 {
            return false;
        }
        self.index = u16::from_le_bytes([buf[0], buf[1]]);
        true
    }

    fn set_from_cc(&mut self, cc: u8) -> bool {
        let Some(d) = self.decl() else { return false };
        self.index = ((cc as u32 * d.steps as u32 + 63) / 127) as u16;
        true
    }
}

/// A choice by index among `n()` named values, saved as one byte.
#[derive(Clone)]
pub struct ChoiceOption<const KIND: u8> {
    pub index: u8,
    key: OptionKey,
}

/// The reverb type: an index in `PROGRAMS`. The firmware loads it when it
/// changes (`App::load_type`).
pub type TypeOption = ChoiceOption<0>;
/// A preset of the active type: 0 is the type's defaults, k its preset k - 1.
pub type PresetOption = ChoiceOption<1>;

impl<const KIND: u8> ChoiceOption<KIND> {
    pub fn new(key: u32) -> Self {
        Self { index: 0, key: OptionKey::new(key) }
    }

    fn n(&self) -> usize {
        match KIND {
            0 => N_PROGRAMS,
            _ => program().presets.len() + 1,
        }
    }

    /// The name of choice `i`.
    pub fn label(&self, i: usize) -> &'static str {
        match KIND {
            0 => PROGRAMS[i.min(N_PROGRAMS - 1)].title,
            _ => match i {
                0 => "default",
                i => program().presets.get(i - 1).map(|p| p.name).unwrap_or("-"),
            },
        }
    }
}

impl<const KIND: u8> OptionTrait for ChoiceOption<KIND> {
    fn name(&self) -> &'static str {
        match KIND {
            0 => "type",
            _ => "preset",
        }
    }

    fn value(&self) -> OptionString {
        let mut s = OptionString::new();
        s.push_str(self.label(self.index as usize)).ok();
        s
    }

    fn tick_up(&mut self) {
        if (self.index as usize) + 1 < self.n() {
            self.index += 1;
        }
    }

    fn tick_down(&mut self) {
        self.index = self.index.saturating_sub(1);
    }

    fn percent(&self) -> f32 {
        let n = self.n().max(2) - 1;
        self.index as f32 / n as f32
    }

    fn n_unique_values(&self) -> usize {
        self.n()
    }

    fn key(&self) -> &OptionKey {
        &self.key
    }

    fn key_mut(&mut self) -> &mut OptionKey {
        &mut self.key
    }

    fn encode(&self, buf: &mut [u8]) -> Option<usize> {
        if buf.is_empty() {
            return None;
        }
        buf[0] = self.index;
        Some(1)
    }

    fn decode(&mut self, buf: &[u8]) -> bool {
        match buf.first() {
            Some(&i) => {
                // The type must exist in this build; a preset index is
                // checked against its type once that has loaded.
                if KIND == 0 && i as usize >= N_PROGRAMS {
                    return false;
                }
                self.index = i;
                true
            }
            None => false,
        }
    }
}

/// The TYPE page: what kind of reverb, and a starting point for it.
#[derive(Clone)]
pub struct TypeOpts {
    pub kind: TypeOption,
    pub preset: PresetOption,
}

impl Default for TypeOpts {
    fn default() -> Self {
        Self { kind: TypeOption::new(0x7e57_0001), preset: PresetOption::new(0x7e57_0002) }
    }
}

impl OptionPage for TypeOpts {
    fn options(&self) -> OptionVec<'_> {
        OptionVec::from_slice(&[&self.kind, &self.preset]).unwrap()
    }

    fn options_mut(&mut self) -> OptionVecMut<'_> {
        let mut r = OptionVecMut::new();
        r.push(&mut self.kind).ok();
        r.push(&mut self.preset).ok();
        r
    }

    fn set_parent_key(&mut self, parent_key: u32) {
        self.kind.key_mut().hash_with(parent_key);
        self.preset.key_mut().hash_with(parent_key);
    }
}

#[derive(Default, Clone, Copy, PartialEq, EnumIter, IntoStaticStr, Serialize, Deserialize)]
#[strum(serialize_all = "kebab-case")]
pub enum Output {
    #[default]
    Reverb,
    Bypass,
    Mute,
}

/// What a CV input expects (`bfr_cpu::cv::Range`).
#[derive(Default, Clone, Copy, PartialEq, EnumIter, IntoStaticStr, Serialize, Deserialize)]
pub enum CvRange {
    #[default]
    #[strum(serialize = "+-5 V")]
    Bipolar5,
    #[strum(serialize = "0-5 V")]
    Unipolar5,
    #[strum(serialize = "0-10 V")]
    Unipolar10,
}

impl CvRange {
    pub fn range(self) -> cv::Range {
        match self {
            CvRange::Bipolar5 => cv::Range::Bipolar5,
            CvRange::Unipolar5 => cv::Range::Unipolar5,
            CvRange::Unipolar10 => cv::Range::Unipolar10,
        }
    }
}

/// Which CV input's rising gate kicks the spring (`bfr/peripheral.py`'s
/// gate detectors).
#[derive(Default, Clone, Copy, PartialEq, EnumIter, IntoStaticStr, Serialize, Deserialize)]
pub enum KickGate {
    #[default]
    #[strum(serialize = "off")]
    Off,
    #[strum(serialize = "CV1")]
    Cv1,
    #[strum(serialize = "CV2")]
    Cv2,
}

impl KickGate {
    /// The gate-edge bit it listens to (`Engine::gate_edges`).
    pub fn mask(self) -> u8 {
        match self {
            KickGate::Off => 0,
            KickGate::Cv1 => 0b01,
            KickGate::Cv2 => 0b10,
        }
    }
}

#[derive(OptionPage, Clone)]
pub struct SettingsOpts {
    #[option]
    pub output: EnumOption<Output>,
    #[option]
    pub cv1_range: EnumOption<CvRange>,
    #[option]
    pub cv2_range: EnumOption<CvRange>,
    #[option]
    pub kick_gate: EnumOption<KickGate>,
}

/// How far one CV moves a slot's parameter: -100..100 % of the parameter's
/// range at the CV's full scale (`bfr_cpu::cv`). Saved as one byte, zero too
/// (an older non-zero depth must not come back).
#[derive(Clone)]
pub struct DepthOption {
    pub percent: i8,
    key: OptionKey,
}

impl DepthOption {
    pub fn new(key: u32) -> Self {
        Self { percent: 0, key: OptionKey::new(key) }
    }

    /// The depth as a fraction, -1..1.
    pub fn fraction(&self) -> f64 {
        self.percent as f64 / 100.0
    }

    pub fn step(&mut self, ticks: i32) {
        self.percent = (self.percent as i32 + ticks).clamp(-100, 100) as i8;
    }
}

impl OptionTrait for DepthOption {
    fn name(&self) -> &'static str {
        "cv-depth"
    }

    fn value(&self) -> OptionString {
        let mut s = OptionString::new();
        write!(&mut s, "{:+}%", self.percent).ok();
        s
    }

    fn tick_up(&mut self) {
        self.step(1);
    }

    fn tick_down(&mut self) {
        self.step(-1);
    }

    fn percent(&self) -> f32 {
        (self.percent as f32 + 100.0) / 200.0
    }

    fn n_unique_values(&self) -> usize {
        201
    }

    fn key(&self) -> &OptionKey {
        &self.key
    }

    fn key_mut(&mut self) -> &mut OptionKey {
        &mut self.key
    }

    fn encode(&self, buf: &mut [u8]) -> Option<usize> {
        if buf.is_empty() {
            return None;
        }
        buf[0] = self.percent as u8;
        Some(1)
    }

    fn decode(&mut self, buf: &[u8]) -> bool {
        match buf.first() {
            Some(&b) => {
                self.percent = (b as i8).clamp(-100, 100);
                true
            }
            None => false,
        }
    }
}

include!(concat!(env!("OUT_DIR"), "/ui.rs"));
